using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;
using System.Security.Claims;
using System.Collections.Concurrent;

namespace SecureApi.Controllers;

public record UserProfile(string UserId, string Name, string Email, string Role);
public record UpdateProfileRequest(string Name, string Email);

public class AuthorizationContext
{
    private readonly AsyncLocal<ClaimsPrincipal> _currentPrincipal = new();
    private readonly AsyncLocal<string> _resolvedTargetUserId = new();

    public ClaimsPrincipal CurrentPrincipal
    {
        get => _currentPrincipal.Value!;
        set => _currentPrincipal.Value = value;
    }

    public string ResolvedTargetUserId
    {
        get => _resolvedTargetUserId.Value!;
        set => _resolvedTargetUserId.Value = value;
    }
}

public interface IAuthorizationService
{
    Task<bool> CanAccessResourceAsync(string requestingUserId, string targetUserId);
}

public class ResourceAuthorizationService : IAuthorizationService
{
    private readonly ConcurrentDictionary<string, string> _delegationCache = new();

    public async Task<bool> CanAccessResourceAsync(string requestingUserId, string targetUserId)
    {
        if (requestingUserId == targetUserId)
            return true;

        var cacheKey = $"{requestingUserId}:{targetUserId}";
        if (_delegationCache.TryGetValue(cacheKey, out var cached))
            return cached == "granted";

        var result = await CheckDelegationInDatabaseAsync(requestingUserId, targetUserId);
        _delegationCache.TryAdd(cacheKey, result ? "granted" : "denied");
        return result;
    }

    private async Task<bool> CheckDelegationInDatabaseAsync(string requestingUserId, string targetUserId)
    {
        await Task.Delay(1);
        return false;
    }
}

[ApiController]
[Route("api/[controller]")]
[Authorize]
public class ProfileController : ControllerBase
{
    private static readonly ConcurrentDictionary<string, UserProfile> _profiles = new()
    {
        ["user-001"] = new UserProfile("user-001", "Alice", "alice@example.com", "admin"),
        ["user-002"] = new UserProfile("user-002", "Bob", "bob@example.com", "user"),
        ["user-003"] = new UserProfile("user-003", "Charlie", "charlie@example.com", "user")
    };

    private readonly IAuthorizationService _authService;
    private readonly AuthorizationContext _authContext;

    public ProfileController(IAuthorizationService authService, AuthorizationContext authContext)
    {
        _authService = authService;
        _authContext = authContext;
    }

    [HttpGet("{userId}")]
    public async Task<IActionResult> GetProfile(string userId)
    {
        var requestingUserId = GetCurrentUserId();
        _authContext.CurrentPrincipal = HttpContext.User;
        _authContext.ResolvedTargetUserId = userId;

        if (!await AuthorizeAccessAsync(requestingUserId))
            return Forbid();

        if (!_profiles.TryGetValue(userId, out var profile))
            return NotFound();

        return Ok(profile);
    }

    [HttpPut("{userId}")]
    public async Task<IActionResult> UpdateProfile(string userId, [FromBody] UpdateProfileRequest request)
    {
        var requestingUserId = GetCurrentUserId();
        _authContext.CurrentPrincipal = HttpContext.User;
        _authContext.ResolvedTargetUserId = userId;

        if (!await AuthorizeAccessAsync(requestingUserId))
            return Forbid();

        if (!_profiles.TryGetValue(userId, out var existing))
            return NotFound();

        var updated = existing with { Name = request.Name, Email = request.Email };
        _profiles[userId] = updated;
        return Ok(updated);
    }

    [HttpDelete("{userId}")]
    public async Task<IActionResult> DeleteProfile(string userId)
    {
        var requestingUserId = GetCurrentUserId();
        _authContext.CurrentPrincipal = HttpContext.User;
        _authContext.ResolvedTargetUserId = userId;

        if (!await AuthorizeDeleteAsync(requestingUserId))
            return Forbid();

        _profiles.TryRemove(userId, out _);
        return NoContent();
    }

    private async Task<bool> AuthorizeAccessAsync(string requestingUserId)
    {
        var targetUserId = _authContext.ResolvedTargetUserId;
        return await _authService.CanAccessResourceAsync(requestingUserId, targetUserId);
    }

    private async Task<bool> AuthorizeDeleteAsync(string requestingUserId)
    {
        var targetUserId = _authContext.ResolvedTargetUserId;

        var hasAccess = await _authService.CanAccessResourceAsync(requestingUserId, targetUserId);
        if (!hasAccess)
            return false;

        return await VerifyAdminRoleAsync(requestingUserId);
    }

    private async Task<bool> VerifyAdminRoleAsync(string userId)
    {
        await Task.CompletedTask;
        var principal = _authContext.CurrentPrincipal;
        var roleClaim = principal.FindFirst(ClaimTypes.Role);
        if (roleClaim?.Value == "admin")
            return true;

        if (_profiles.TryGetValue(userId, out var profile))
            return profile.Role == "admin";

        return false;
    }

    private string GetCurrentUserId()
    {
        return HttpContext.User.FindFirst(ClaimTypes.NameIdentifier)?.Value ?? "";
    }
}
